//! Experimental bounded native runtime for separate cached ONNX prefill/decode graphs.
//! Model inputs and generated bytes are kept in memory and are never logged.

use std::{
    borrow::Cow,
    fs::File,
    io::{self, BufRead, Read, Write},
    path::Path,
};

use prost::Message;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tract::prelude::*;
use tract_onnx::pb::{self, type_proto::Value as TypeValue};

#[cfg(feature = "embedded-owned-cached-byte")]
mod embedded {
    include!(concat!(env!("OUT_DIR"), "/embedded_owned_cached.rs"));
}

const BYTE_VOCABULARY: usize = 256;
const F32_BYTES: u64 = 4;

type Result<T> = std::result::Result<T, &'static str>;

#[derive(Clone, Debug, Deserialize, PartialEq, Eq)]
pub struct Architecture {
    width: usize,
    layers: usize,
    heads: usize,
    conv_kernel: usize,
    context: usize,
    ff_multiplier: usize,
    attention_every: usize,
}

#[derive(Clone, Debug, Deserialize, PartialEq, Eq)]
pub struct CacheState {
    name: String,
    kind: String,
    layer: usize,
    dtype: String,
    shape: Vec<serde_json::Value>,
    capacity: usize,
}

#[derive(Clone, Debug, Deserialize)]
struct GraphContract {
    file: String,
    inputs: Vec<String>,
    outputs: Vec<String>,
    input_dtype: Option<String>,
    token_dtype: Option<String>,
    position_dtype: Option<String>,
    logit_dtype: String,
    input_shape: Option<Vec<serde_json::Value>>,
    token_shape: Option<Vec<serde_json::Value>>,
    position_shape: Option<Vec<serde_json::Value>>,
    sequence_min: Option<usize>,
    sequence_max: Option<usize>,
    consumes_one_token: Option<bool>,
}

#[derive(Clone, Debug, Deserialize)]
struct CacheContract {
    states: Vec<CacheState>,
    attention_cache_length_must_equal_position: bool,
    capacity: usize,
    maximum_state_bytes_per_batch: u64,
    overflow: String,
    eviction: String,
    initial_attention_cache_shape: Vec<serde_json::Value>,
    initial_convolution_cache: String,
}

#[derive(Clone, Debug, Deserialize)]
struct Manifest {
    schema_version: String,
    artifact_version: u64,
    promotion_eligible: bool,
    model_sha256: String,
    source_manifest_sha256: String,
    source_model_code_sha256: String,
    prefill_onnx_sha256: String,
    decode_onnx_sha256: String,
    prefill: GraphContract,
    decode: GraphContract,
    cache: CacheContract,
    architecture: Architecture,
    context: usize,
    vocabulary: usize,
    dtype: String,
    opset: u64,
}

#[derive(Clone, Debug, Deserialize)]
pub struct RuntimeLimits {
    schema_version: String,
    max_manifest_bytes: u64,
    max_model_bytes: u64,
    max_context: usize,
    max_line_bytes: usize,
    max_generation_bytes: Option<usize>,
    max_examples: Option<usize>,
}

fn validate_runtime_limits(
    runtime: &RuntimeLimits,
    limit: usize,
    stop: Option<&[u8]>,
    max_total_graph_bytes: u64,
    max_cache_bytes: u64,
) -> Result<()> {
    if runtime.schema_version != "lfg.owned-byte-runtime.v1"
        || runtime.max_manifest_bytes == 0
        || runtime.max_model_bytes == 0
        || runtime.max_context == 0
        || runtime.max_line_bytes == 0
        || runtime.max_examples.unwrap_or(1) == 0
    {
        return Err("invalid cached runtime configuration limits");
    }
    if limit == 0
        || runtime
            .max_generation_bytes
            .is_none_or(|maximum| limit > maximum)
    {
        return Err("cached generation limit exceeds runtime maximum");
    }
    if stop.is_some_and(|sequence| sequence.is_empty() || sequence.len() > limit) {
        return Err("cached stop sequence exceeds generation limit");
    }
    if max_total_graph_bytes == 0 || max_cache_bytes == 0 {
        return Err("cached graph or cache-state limit is zero");
    }
    Ok(())
}

#[derive(Clone, Debug)]
pub struct CachedIdentity {
    pub manifest_sha256: String,
    pub model_sha256: String,
    pub source_manifest_sha256: String,
    pub prefill_onnx_sha256: String,
    pub decode_onnx_sha256: String,
    pub context: usize,
    pub maximum_state_bytes_per_batch: u64,
    pub total_graph_bytes: u64,
    pub architecture: Architecture,
    pub states: Vec<CacheState>,
}

#[derive(Clone)]
enum Artifact<'a> {
    Directory(&'a Path),
    #[cfg(feature = "embedded-owned-cached-byte")]
    Embedded,
}

impl Artifact<'_> {
    fn file_len(&self, name: &str, maximum: u64) -> Result<u64> {
        match self {
            Self::Directory(root) => {
                let metadata = std::fs::symlink_metadata(root.join(name))
                    .map_err(|_| "cached artifact unavailable")?;
                if !metadata.file_type().is_file() || metadata.len() > maximum {
                    return Err("cached artifact is not a bounded regular file");
                }
                Ok(metadata.len())
            }
            #[cfg(feature = "embedded-owned-cached-byte")]
            Self::Embedded => Ok(match name {
                "manifest.json" => embedded::MANIFEST.len() as u64,
                "prefill.onnx" => embedded::PREFILL.len() as u64,
                "decode.onnx" => embedded::DECODE.len() as u64,
                _ => return Err("unknown embedded cached artifact file"),
            }),
        }
    }

    fn read(&self, name: &str, maximum: u64) -> Result<Cow<'_, [u8]>> {
        match self {
            Self::Directory(root) => {
                Ok(Cow::Owned(read_regular_bounded(&root.join(name), maximum)?))
            }
            #[cfg(feature = "embedded-owned-cached-byte")]
            Self::Embedded => {
                let data = match name {
                    "manifest.json" => embedded::MANIFEST,
                    "prefill.onnx" => embedded::PREFILL,
                    "decode.onnx" => embedded::DECODE,
                    _ => return Err("unknown embedded cached artifact file"),
                };
                if data.len() as u64 > maximum {
                    return Err("embedded cached artifact exceeds configured size");
                }
                Ok(Cow::Borrowed(data))
            }
        }
    }
}

fn sha256(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn valid_sha256(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn read_regular_bounded(path: &Path, maximum: u64) -> Result<Vec<u8>> {
    if maximum == 0 {
        return Err("cached artifact limit is zero");
    }
    let metadata = std::fs::symlink_metadata(path).map_err(|_| "cached artifact unavailable")?;
    if !metadata.file_type().is_file() || metadata.len() > maximum {
        return Err("cached artifact is not a bounded regular file");
    }
    let mut bytes = Vec::with_capacity(metadata.len().min(maximum) as usize);
    File::open(path)
        .map_err(|_| "cached artifact unavailable")?
        .take(
            maximum
                .checked_add(1)
                .ok_or("cached artifact limit overflow")?,
        )
        .read_to_end(&mut bytes)
        .map_err(|_| "cached artifact unreadable")?;
    if bytes.len() as u64 > maximum {
        return Err("cached artifact exceeds configured size");
    }
    Ok(bytes)
}

fn checked_architecture(architecture: &Architecture) -> Result<()> {
    if architecture.width == 0
        || architecture.layers == 0
        || architecture.heads == 0
        || architecture.conv_kernel == 0
        || architecture.context == 0
        || architecture.ff_multiplier == 0
        || architecture.attention_every == 0
        || architecture.width % architecture.heads != 0
    {
        return Err("invalid cached model architecture");
    }
    architecture
        .width
        .checked_mul(architecture.ff_multiplier)
        .ok_or("cached model architecture overflow")?;
    Ok(())
}

fn expected_states(architecture: &Architecture) -> Result<Vec<CacheState>> {
    checked_architecture(architecture)?;
    let mut states = Vec::new();
    for layer in 0..architecture.layers {
        if architecture.conv_kernel > 1 {
            states.push(CacheState {
                name: format!("conv_{layer}"),
                kind: "depthwise-convolution-history".to_owned(),
                layer,
                dtype: "float32".to_owned(),
                shape: vec![
                    serde_json::json!("batch"),
                    serde_json::json!(architecture.width),
                    serde_json::json!(architecture.conv_kernel - 1),
                ],
                capacity: architecture.conv_kernel - 1,
            });
        }
        if (layer + 1) % architecture.attention_every == 0 {
            let head_width = architecture.width / architecture.heads;
            for (name, kind) in [
                (format!("key_{layer}"), "attention-key"),
                (format!("value_{layer}"), "attention-value"),
            ] {
                states.push(CacheState {
                    name,
                    kind: kind.to_owned(),
                    layer,
                    dtype: "float32".to_owned(),
                    shape: vec![
                        serde_json::json!("batch"),
                        serde_json::json!(architecture.heads),
                        serde_json::json!("position"),
                        serde_json::json!(head_width),
                    ],
                    capacity: architecture.context,
                });
            }
        }
    }
    Ok(states)
}

fn validate_architecture_resource_bounds(
    architecture: &Architecture,
    maximum_layers: usize,
    maximum_state_bytes: u64,
) -> Result<(u64, u64)> {
    checked_architecture(architecture)?;
    if architecture.layers > maximum_layers {
        return Err("cached model layers exceed configured structural bounds");
    }
    let layers = u64::try_from(architecture.layers).map_err(|_| "cached layer count overflow")?;
    let attention_layers = layers
        / u64::try_from(architecture.attention_every)
            .map_err(|_| "cached attention interval overflow")?;
    let conv_states = if architecture.conv_kernel > 1 {
        layers
    } else {
        0
    };
    let attention_states = attention_layers
        .checked_mul(2)
        .ok_or("cached state count overflow")?;
    let state_count = conv_states
        .checked_add(attention_states)
        .ok_or("cached state count overflow")?;
    let width = u64::try_from(architecture.width).map_err(|_| "cached width overflow")?;
    let kernel_history = u64::try_from(architecture.conv_kernel - 1)
        .map_err(|_| "cached convolution history overflow")?;
    let context = u64::try_from(architecture.context).map_err(|_| "cached context overflow")?;
    let head_count = u64::try_from(architecture.heads).map_err(|_| "cached head count overflow")?;
    let head_width = u64::try_from(architecture.width / architecture.heads)
        .map_err(|_| "cached head width overflow")?;
    let conv_bytes = width
        .checked_mul(kernel_history)
        .and_then(|value| value.checked_mul(F32_BYTES))
        .and_then(|value| value.checked_mul(conv_states))
        .ok_or("cached convolution state size overflow")?;
    let attention_bytes = head_count
        .checked_mul(context)
        .and_then(|value| value.checked_mul(head_width))
        .and_then(|value| value.checked_mul(F32_BYTES))
        .and_then(|value| value.checked_mul(attention_states))
        .ok_or("cached attention state size overflow")?;
    let state_bytes = conv_bytes
        .checked_add(attention_bytes)
        .ok_or("cached state size overflow")?;
    if state_bytes > maximum_state_bytes {
        return Err("cached state exceeds configured cache-state bound");
    }
    Ok((state_count, state_bytes))
}

fn expected_state_bytes(architecture: &Architecture, states: &[CacheState]) -> Result<u64> {
    let mut values = 0_u64;
    for state in states {
        let elements = match state.kind.as_str() {
            "depthwise-convolution-history" => {
                (architecture.width as u64).checked_mul((architecture.conv_kernel - 1) as u64)
            }
            "attention-key" | "attention-value" => (architecture.heads as u64)
                .checked_mul(architecture.context as u64)
                .and_then(|n| n.checked_mul((architecture.width / architecture.heads) as u64)),
            _ => return Err("unknown cache state kind"),
        }
        .ok_or("cache state budget overflow")?;
        values = values
            .checked_add(elements)
            .ok_or("cache state budget overflow")?;
    }
    values
        .checked_mul(F32_BYTES)
        .ok_or("cache state byte budget overflow")
}

fn validate_graph_contracts(
    manifest: &Manifest,
    manifest_sha256: &str,
    max_manifest_bytes: u64,
    max_total_graph_bytes: u64,
    max_cache_bytes: u64,
) -> Result<()> {
    let architecture = &manifest.architecture;
    checked_architecture(architecture)?;
    if manifest.schema_version != "lfg.owned-byte-cached-onnx.v1"
        || manifest.artifact_version != 1
        || manifest.promotion_eligible
        || manifest.vocabulary != BYTE_VOCABULARY
        || manifest.dtype != "float32"
        || manifest.opset == 0
        || manifest.context != architecture.context
        || manifest.context == 0
        || !valid_sha256(&manifest.model_sha256)
        || !valid_sha256(&manifest.source_manifest_sha256)
        || !valid_sha256(&manifest.source_model_code_sha256)
        || !valid_sha256(&manifest.prefill_onnx_sha256)
        || !valid_sha256(&manifest.decode_onnx_sha256)
        || !valid_sha256(manifest_sha256)
    {
        return Err("unsupported or malformed cached manifest");
    }
    let structural_limit =
        usize::try_from(max_manifest_bytes.min(max_total_graph_bytes)).unwrap_or(usize::MAX);
    let (expected_state_count, expected_state_byte_bound) =
        validate_architecture_resource_bounds(architecture, structural_limit, max_cache_bytes)?;
    if expected_state_count != manifest.cache.states.len() as u64
        || expected_state_byte_bound != manifest.cache.maximum_state_bytes_per_batch
    {
        return Err("cached manifest state bounds mismatch");
    }
    let states = expected_states(architecture)?;
    if states != manifest.cache.states
        || manifest.cache.capacity != architecture.context
        || manifest.cache.maximum_state_bytes_per_batch
            != expected_state_bytes(architecture, &states)?
        || !manifest.cache.attention_cache_length_must_equal_position
        || manifest.cache.overflow != "reject"
        || manifest.cache.eviction != "none"
        || manifest.cache.initial_attention_cache_shape
            != vec![
                serde_json::json!("batch"),
                serde_json::json!("heads"),
                serde_json::json!(0),
                serde_json::json!("head_dim"),
            ]
        || manifest.cache.initial_convolution_cache != "zeros with declared fixed shape"
    {
        return Err("cached manifest state layout or capacity mismatch");
    }
    let state_names: Vec<_> = states.iter().map(|state| state.name.clone()).collect();
    let prefill_outputs = std::iter::once("logits".to_owned())
        .chain(state_names.iter().cloned())
        .collect::<Vec<_>>();
    let decode_inputs = std::iter::once("token".to_owned())
        .chain(std::iter::once("position".to_owned()))
        .chain(state_names.iter().cloned())
        .collect::<Vec<_>>();
    let decode_outputs = std::iter::once("logits".to_owned())
        .chain(state_names.iter().map(|name| format!("{name}_out")))
        .collect::<Vec<_>>();
    if manifest.prefill.file != "prefill.onnx"
        || manifest.prefill.inputs != ["tokens"]
        || manifest.prefill.outputs != prefill_outputs
        || manifest.prefill.input_dtype.as_deref() != Some("int64")
        || manifest.prefill.logit_dtype != "float32"
        || manifest.prefill.input_shape
            != Some(vec![
                serde_json::json!("batch"),
                serde_json::json!("sequence"),
            ])
        || manifest.prefill.sequence_min != Some(1)
        || manifest.prefill.sequence_max != Some(architecture.context)
        || manifest.decode.file != "decode.onnx"
        || manifest.decode.inputs != decode_inputs
        || manifest.decode.outputs != decode_outputs
        || manifest.decode.token_dtype.as_deref() != Some("int64")
        || manifest.decode.position_dtype.as_deref() != Some("int64")
        || manifest.decode.token_shape != Some(vec![serde_json::json!("batch")])
        || manifest.decode.position_shape != Some(vec![])
        || manifest.decode.logit_dtype != "float32"
        || manifest.decode.consumes_one_token != Some(true)
    {
        return Err("cached graph contract does not match the manifest layout");
    }
    Ok(())
}

fn tensor_info(value: &pb::ValueInfoProto) -> Result<(i32, Vec<Dimension>)> {
    let ty = value.r#type.as_ref().ok_or("ONNX value type is missing")?;
    let tensor = match ty.value.as_ref() {
        Some(TypeValue::TensorType(tensor)) => tensor,
        _ => return Err("cached ONNX value must be a tensor"),
    };
    let shape = tensor
        .shape
        .as_ref()
        .ok_or("ONNX tensor shape is missing")?;
    let dimensions = shape
        .dim
        .iter()
        .map(|dimension| match &dimension.value {
            Some(pb::tensor_shape_proto::dimension::Value::DimValue(value)) if *value >= 0 => {
                Ok(Dimension::Fixed(*value as usize))
            }
            Some(pb::tensor_shape_proto::dimension::Value::DimParam(value))
                if !value.is_empty() =>
            {
                Ok(Dimension::Symbol(value.clone()))
            }
            _ => Err("invalid ONNX dimension"),
        })
        .collect::<Result<Vec<_>>>()?;
    Ok((tensor.elem_type, dimensions))
}

#[derive(Debug, PartialEq, Eq)]
enum Dimension {
    Fixed(usize),
    Symbol(String),
}

fn dynamic_or_fixed_dimension(dimension: &Dimension, fixed: usize) -> bool {
    matches!(dimension, Dimension::Fixed(value) if *value == fixed)
        || matches!(dimension, Dimension::Symbol(value) if !value.is_empty())
}

fn validate_value_info(
    value: &pb::ValueInfoProto,
    expected_name: &str,
    expected_type: i32,
    expected_shape: &[Option<usize>],
) -> Result<()> {
    if value.name != expected_name {
        return Err("cached ONNX tensor names or order do not match the manifest");
    }
    let (datum_type, dimensions) = tensor_info(value)?;
    if datum_type != expected_type || dimensions.len() != expected_shape.len() {
        return Err("cached ONNX tensor dtype or rank mismatch");
    }
    for (actual, expected) in dimensions.iter().zip(expected_shape) {
        let matches = match expected {
            Some(fixed) => dynamic_or_fixed_dimension(actual, *fixed),
            None => matches!(actual, Dimension::Symbol(value) if !value.is_empty()),
        };
        if !matches {
            return Err("cached ONNX tensor shape does not match the architecture");
        }
    }
    Ok(())
}

fn tensor_has_external_data(tensor: &pb::TensorProto) -> bool {
    tensor.data_location == Some(pb::tensor_proto::DataLocation::External as i32)
        || !tensor.external_data.is_empty()
}

fn sparse_has_external_data(tensor: &pb::SparseTensorProto) -> bool {
    tensor.values.as_ref().is_some_and(tensor_has_external_data)
        || tensor
            .indices
            .as_ref()
            .is_some_and(tensor_has_external_data)
}

fn node_has_external_data(node: &pb::NodeProto) -> bool {
    node.attribute.iter().any(|attribute| {
        attribute.t.as_ref().is_some_and(tensor_has_external_data)
            || attribute.tensors.iter().any(tensor_has_external_data)
            || attribute
                .sparse_tensor
                .as_ref()
                .is_some_and(sparse_has_external_data)
            || attribute
                .sparse_tensors
                .iter()
                .any(sparse_has_external_data)
            || attribute.g.as_ref().is_some_and(graph_has_external_data)
            || attribute.graphs.iter().any(graph_has_external_data)
    })
}

fn graph_has_external_data(graph: &pb::GraphProto) -> bool {
    graph.initializer.iter().any(tensor_has_external_data)
        || graph
            .sparse_initializer
            .iter()
            .any(sparse_has_external_data)
        || graph.node.iter().any(node_has_external_data)
}

fn validate_onnx_graph(raw: &[u8], prefill: bool, manifest: &Manifest) -> Result<()> {
    let model = pb::ModelProto::decode(raw).map_err(|_| "cached ONNX graph protobuf is invalid")?;
    let default_opsets = model
        .opset_import
        .iter()
        .filter(|opset| opset.domain.is_empty() || opset.domain == "ai.onnx")
        .collect::<Vec<_>>();
    if model.ir_version <= 0
        || default_opsets.len() != 1
        || default_opsets[0].version != manifest.opset as i64
        || model
            .opset_import
            .iter()
            .any(|opset| !opset.domain.is_empty() && opset.domain != "ai.onnx")
    {
        return Err("cached ONNX version or operator domain mismatch");
    }
    let graph = model.graph.as_ref().ok_or("cached ONNX graph is missing")?;
    if graph_has_external_data(graph)
        || model
            .functions
            .iter()
            .any(|function| function.node.iter().any(node_has_external_data))
        || model.training_info.iter().any(|training| {
            training
                .initialization
                .as_ref()
                .is_some_and(graph_has_external_data)
                || training
                    .algorithm
                    .as_ref()
                    .is_some_and(graph_has_external_data)
        })
    {
        return Err("external ONNX tensor data is unsupported");
    }
    let states = &manifest.cache.states;
    if prefill {
        let mut outputs = vec![(
            "logits".to_owned(),
            1_i32,
            vec![None, Some(BYTE_VOCABULARY)],
        )];
        for state in states {
            outputs.push((
                state.name.clone(),
                1_i32,
                shape_for_state(state, &manifest.architecture)?,
            ));
        }
        let input = graph.input.as_slice();
        if input.len() != 1 || graph.output.len() != outputs.len() {
            return Err("cached prefill graph arity mismatch");
        }
        validate_value_info(&input[0], "tokens", 7, &[None, None])?;
        validate_outputs(&graph.output, &outputs)?;
        return Ok(());
    } else {
        let mut inputs = vec![
            ("token".to_owned(), 7_i32, vec![None]),
            ("position".to_owned(), 7_i32, vec![]),
        ];
        for state in states {
            inputs.push((
                state.name.clone(),
                1_i32,
                shape_for_state(state, &manifest.architecture)?,
            ));
        }
        let mut outputs = vec![(
            "logits".to_owned(),
            1_i32,
            vec![None, Some(BYTE_VOCABULARY)],
        )];
        for state in states {
            outputs.push((
                format!("{}_out", state.name),
                1_i32,
                shape_for_state(state, &manifest.architecture)?,
            ));
        }
        if graph.input.len() != inputs.len() || graph.output.len() != outputs.len() {
            return Err("cached decode graph arity mismatch");
        }
        validate_outputs(&graph.input, &inputs)?;
        validate_outputs(&graph.output, &outputs)?;
        return Ok(());
    }
    #[allow(unreachable_code)]
    Err("invalid cached graph")
}

fn validate_outputs(
    values: &[pb::ValueInfoProto],
    expected: &[(String, i32, Vec<Option<usize>>)],
) -> Result<()> {
    if values.len() != expected.len() {
        return Err("cached ONNX graph arity mismatch");
    }
    for (value, (name, datum_type, shape)) in values.iter().zip(expected) {
        validate_value_info(value, name, *datum_type, shape)?;
    }
    Ok(())
}

fn shape_for_state(state: &CacheState, architecture: &Architecture) -> Result<Vec<Option<usize>>> {
    match state.kind.as_str() {
        "depthwise-convolution-history" => Ok(vec![
            Some(1),
            Some(architecture.width),
            Some(architecture.conv_kernel - 1),
        ]),
        "attention-key" | "attention-value" => Ok(vec![
            Some(1),
            Some(architecture.heads),
            None,
            Some(architecture.width / architecture.heads),
        ]),
        _ => Err("unknown cached input state kind"),
    }
}

fn validate_graph_metadata(
    prefill_raw: &[u8],
    decode_raw: &[u8],
    manifest: &Manifest,
) -> Result<()> {
    validate_onnx_graph(prefill_raw, true, manifest)?;
    validate_onnx_graph(decode_raw, false, manifest)
}

fn validate_manifest_and_graph_bytes(
    manifest_raw: &[u8],
    prefill_raw: &[u8],
    decode_raw: &[u8],
    expected_manifest_sha256: &str,
    expected_model_sha256: Option<&str>,
    max_manifest_bytes: u64,
    max_context: usize,
    max_model_bytes: u64,
    max_total_graph_bytes: u64,
    max_cache_bytes: u64,
) -> Result<(Manifest, CachedIdentity)> {
    if !valid_sha256(expected_manifest_sha256)
        || sha256(manifest_raw) != expected_manifest_sha256
        || prefill_raw.len() as u64 > max_model_bytes
        || decode_raw.len() as u64 > max_model_bytes
    {
        return Err("cached manifest pin or graph byte limits mismatch");
    }
    let total_graph_bytes = (prefill_raw.len() as u64)
        .checked_add(decode_raw.len() as u64)
        .ok_or("cached graph byte budget overflow")?;
    if total_graph_bytes > max_total_graph_bytes {
        return Err("cached graphs exceed total artifact byte budget");
    }
    let manifest: Manifest =
        serde_json::from_slice(manifest_raw).map_err(|_| "invalid cached manifest")?;
    validate_graph_contracts(
        &manifest,
        expected_manifest_sha256,
        max_manifest_bytes,
        max_total_graph_bytes,
        max_cache_bytes,
    )?;
    if manifest.context > max_context
        || expected_model_sha256.is_some_and(|expected| expected != manifest.model_sha256)
        || manifest.cache.maximum_state_bytes_per_batch > max_cache_bytes
        || sha256(prefill_raw) != manifest.prefill_onnx_sha256
        || sha256(decode_raw) != manifest.decode_onnx_sha256
    {
        return Err("cached artifact identity or resource limits mismatch");
    }
    validate_graph_metadata(prefill_raw, decode_raw, &manifest)?;
    let identity = CachedIdentity {
        manifest_sha256: expected_manifest_sha256.to_owned(),
        model_sha256: manifest.model_sha256.clone(),
        source_manifest_sha256: manifest.source_manifest_sha256.clone(),
        prefill_onnx_sha256: manifest.prefill_onnx_sha256.clone(),
        decode_onnx_sha256: manifest.decode_onnx_sha256.clone(),
        context: manifest.context,
        maximum_state_bytes_per_batch: manifest.cache.maximum_state_bytes_per_batch,
        total_graph_bytes,
        architecture: manifest.architecture.clone(),
        states: manifest.cache.states.clone(),
    };
    Ok((manifest, identity))
}

pub fn validate_directory(
    root: &Path,
    expected_manifest_sha256: &str,
    expected_model_sha256: &str,
    max_manifest_bytes: u64,
    max_context: usize,
    max_model_bytes: u64,
    max_total_graph_bytes: u64,
    max_cache_bytes: u64,
) -> Result<CachedIdentity> {
    let metadata = std::fs::symlink_metadata(root).map_err(|_| "cached artifact unavailable")?;
    if !metadata.file_type().is_dir() {
        return Err("cached artifact directory must be a real directory");
    }
    let manifest = read_regular_bounded(&root.join("manifest.json"), max_manifest_bytes)?;
    if !valid_sha256(expected_manifest_sha256) || sha256(&manifest) != expected_manifest_sha256 {
        return Err("cached manifest identity mismatch");
    }
    let parsed: Manifest =
        serde_json::from_slice(&manifest).map_err(|_| "invalid cached manifest")?;
    validate_graph_contracts(
        &parsed,
        expected_manifest_sha256,
        max_manifest_bytes,
        max_total_graph_bytes,
        max_cache_bytes,
    )?;
    if parsed.context > max_context
        || parsed.model_sha256 != expected_model_sha256
        || parsed.cache.maximum_state_bytes_per_batch > max_cache_bytes
    {
        return Err("cached artifact exceeds configured context or cache limits");
    }
    let prefill_len = Artifact::Directory(root).file_len("prefill.onnx", max_model_bytes)?;
    let decode_len = Artifact::Directory(root).file_len("decode.onnx", max_model_bytes)?;
    if prefill_len
        .checked_add(decode_len)
        .ok_or("cached graph byte budget overflow")?
        > max_total_graph_bytes
    {
        return Err("cached graphs exceed total artifact byte budget");
    }
    let prefill = read_regular_bounded(&root.join("prefill.onnx"), max_model_bytes)?;
    let decode = read_regular_bounded(&root.join("decode.onnx"), max_model_bytes)?;
    let (_, identity) = validate_manifest_and_graph_bytes(
        &manifest,
        &prefill,
        &decode,
        expected_manifest_sha256,
        Some(expected_model_sha256),
        max_manifest_bytes,
        max_context,
        max_model_bytes,
        max_total_graph_bytes,
        max_cache_bytes,
    )?;
    Ok(identity)
}

#[cfg(feature = "embedded-owned-cached-byte")]
pub fn validate_embedded(
    expected_manifest_sha256: &str,
    expected_model_sha256: &str,
    max_manifest_bytes: u64,
    max_context: usize,
    max_model_bytes: u64,
    max_total_graph_bytes: u64,
    max_cache_bytes: u64,
) -> Result<CachedIdentity> {
    if embedded::MANIFEST_SHA256 != expected_manifest_sha256 {
        return Err("embedded cached manifest identity mismatch");
    }
    let (_, identity) = validate_manifest_and_graph_bytes(
        embedded::MANIFEST,
        embedded::PREFILL,
        embedded::DECODE,
        expected_manifest_sha256,
        Some(expected_model_sha256),
        max_manifest_bytes,
        max_context,
        max_model_bytes,
        max_total_graph_bytes,
        max_cache_bytes,
    )?;
    if embedded::MANIFEST.len() as u64 > max_manifest_bytes {
        return Err("embedded cached manifest exceeds configured size");
    }
    Ok(identity)
}

#[cfg(not(feature = "embedded-owned-cached-byte"))]
pub fn validate_embedded(
    _expected_manifest_sha256: &str,
    _expected_model_sha256: &str,
    _max_manifest_bytes: u64,
    _max_context: usize,
    _max_model_bytes: u64,
    _max_total_graph_bytes: u64,
    _max_cache_bytes: u64,
) -> Result<CachedIdentity> {
    Err("embedded cached runtime was not built")
}

fn configure_prefill(raw: &[u8]) -> Result<Runnable> {
    let mut model = tract::onnx()
        .map_err(|_| "tract ONNX runtime is unavailable")?
        .load_buffer(raw)
        .map_err(|_| "cached prefill graph could not be loaded by tract")?;
    if model
        .input_count()
        .map_err(|_| "invalid cached prefill graph")?
        != 1
        || model
            .output_count()
            .map_err(|_| "invalid cached prefill graph")?
            == 0
    {
        return Err("cached prefill graph arity mismatch");
    }
    model
        .set_input_fact(0, "1,S,i64")
        .map_err(|_| "cached prefill graph input fact mismatch")?;
    model
        .into_model()
        .map_err(|_| "cached prefill graph typing failed")?
        .into_runnable()
        .map_err(|_| "cached prefill graph compilation failed")
}

fn configure_decode(
    raw: &[u8],
    states: &[CacheState],
    architecture: &Architecture,
) -> Result<Runnable> {
    let mut model = tract::onnx()
        .map_err(|_| "tract ONNX runtime is unavailable")?
        .load_buffer(raw)
        .map_err(|_| "cached decode graph could not be loaded by tract")?;
    if model
        .input_count()
        .map_err(|_| "invalid cached decode graph")?
        != states.len() + 2
        || model
            .output_count()
            .map_err(|_| "invalid cached decode graph")?
            != states.len() + 1
    {
        return Err("cached decode graph arity mismatch");
    }
    model
        .set_input_fact(0, "1,i64")
        .map_err(|_| "cached decode token input fact mismatch")?;
    model
        .set_input_fact(1, "i64")
        .map_err(|_| "cached decode position input fact mismatch")?;
    for (index, state) in states.iter().enumerate() {
        let shape = match state.kind.as_str() {
            "depthwise-convolution-history" => format!(
                "1,{},{},f32",
                architecture.width,
                architecture.conv_kernel - 1
            ),
            "attention-key" | "attention-value" => format!(
                "1,{},P,{},f32",
                architecture.heads,
                architecture.width / architecture.heads
            ),
            _ => return Err("unknown cached state in decode graph"),
        };
        model
            .set_input_fact(index + 2, shape.as_str())
            .map_err(|_| "cached decode state input fact mismatch")?;
    }
    model
        .into_model()
        .map_err(|_| "cached decode graph typing failed")?
        .into_runnable()
        .map_err(|_| "cached decode graph compilation failed")
}

fn is_f32_shape(tensor: &Tensor, expected: &[usize]) -> bool {
    tensor
        .datum_type()
        .is_ok_and(|dtype| dtype == f32::datum_type())
        && tensor.shape().is_ok_and(|shape| shape == expected)
}

fn greedy(tensor: &Tensor) -> Result<i64> {
    if !is_f32_shape(tensor, &[1, BYTE_VOCABULARY]) {
        return Err("cached model logits have wrong dtype or shape");
    }
    let values = tensor
        .as_slice::<f32>()
        .map_err(|_| "cached logits are not float32")?;
    if values.len() != BYTE_VOCABULARY || values.iter().any(|value| !value.is_finite()) {
        return Err("cached model logits are invalid");
    }
    let mut best = 0;
    for index in 1..values.len() {
        if values[index] > values[best] {
            best = index;
        }
    }
    Ok(best as i64)
}

fn validate_states(
    outputs: &[Tensor],
    states: &[CacheState],
    architecture: &Architecture,
    position: usize,
) -> Result<()> {
    if outputs.len() != states.len() {
        return Err("cached graph returned the wrong number of states");
    }
    for (tensor, state) in outputs.iter().zip(states) {
        let expected = match state.kind.as_str() {
            "depthwise-convolution-history" => {
                vec![1, architecture.width, architecture.conv_kernel - 1]
            }
            "attention-key" | "attention-value" => vec![
                1,
                architecture.heads,
                position,
                architecture.width / architecture.heads,
            ],
            _ => return Err("cached graph returned an unknown state"),
        };
        if !is_f32_shape(tensor, &expected) {
            return Err("cached graph state dtype or shape mismatch");
        }
        let values = tensor
            .as_slice::<f32>()
            .map_err(|_| "cached graph state is not float32")?;
        if values.iter().any(|value| !value.is_finite()) {
            return Err("cached graph state contains non-finite values");
        }
    }
    Ok(())
}

fn stop_matches(generated: &[u8], stop: Option<&[u8]>) -> bool {
    stop.is_some_and(|sequence| !sequence.is_empty() && generated.ends_with(sequence))
}

fn next_decode_position(prompt_len: usize, generated_len: usize, context: usize) -> Option<usize> {
    let position = prompt_len.checked_add(generated_len.checked_sub(1)?)?;
    (position < context).then_some(position)
}

fn generate_with_models(
    prefill: &Runnable,
    decode: &Runnable,
    manifest: &Manifest,
    input: &[u8],
    limit: usize,
    stop: Option<&[u8]>,
) -> Result<(Vec<u8>, &'static str)> {
    if input.is_empty() || input.len() > manifest.context || limit == 0 {
        return Err("invalid cached generation input or limit");
    }
    let token_ids = input
        .iter()
        .map(|byte| i64::from(*byte))
        .collect::<Vec<_>>();
    let mut state = prefill
        .run(vec![
            Tensor::from_slice(&[1, token_ids.len()], &token_ids)
                .map_err(|_| "cached prefill input construction failed")?,
        ])
        .map_err(|_| "cached prefill execution failed")?;
    if state.len() != manifest.cache.states.len() + 1 {
        return Err("cached prefill output arity mismatch");
    }
    if !is_f32_shape(&state[0], &[1, BYTE_VOCABULARY]) {
        return Err("cached prefill logits shape or dtype mismatch");
    }
    validate_states(
        &state[1..],
        &manifest.cache.states,
        &manifest.architecture,
        input.len(),
    )?;
    let mut generated = Vec::with_capacity(limit.min(4096));
    while generated.len() < limit {
        let byte = greedy(&state[0])? as u8;
        generated.push(byte);
        if stop_matches(&generated, stop) {
            return Ok((generated, "stop_sequence"));
        }
        if generated.len() >= limit {
            return Ok((generated, "byte_limit"));
        }
        let Some(position) = next_decode_position(input.len(), generated.len(), manifest.context)
        else {
            return Ok((generated, "context_limit"));
        };
        let token = [i64::from(byte)];
        let consumed = position.checked_add(1).ok_or("cached position overflow")?;
        let position_i64 =
            i64::try_from(position).map_err(|_| "cached absolute position exceeds i64")?;
        let position_tensor = Tensor::from_slice(&[], &[position_i64])
            .map_err(|_| "cached position input construction failed")?;
        let mut inputs = vec![
            Tensor::from_slice(&[1], &token)
                .map_err(|_| "cached decode input construction failed")?,
            position_tensor,
        ];
        inputs.extend(state.into_iter().skip(1));
        state = decode
            .run(inputs)
            .map_err(|_| "cached decode execution failed")?;
        if state.len() != manifest.cache.states.len() + 1 {
            return Err("cached decode output arity mismatch");
        }
        if !is_f32_shape(&state[0], &[1, BYTE_VOCABULARY]) {
            return Err("cached decode logits shape or dtype mismatch");
        }
        validate_states(
            &state[1..],
            &manifest.cache.states,
            &manifest.architecture,
            consumed,
        )?;
    }
    Ok((generated, "byte_limit"))
}

#[derive(Deserialize)]
struct Request {
    id: String,
    text: String,
}

#[derive(Serialize)]
struct Generation<'a> {
    schema_version: &'static str,
    id: &'a str,
    input_bytes: usize,
    generated_bytes: &'a [u8],
    #[serde(skip_serializing_if = "Option::is_none")]
    text: Option<&'a str>,
    stop_reason: &'static str,
}

pub fn generate_directory(
    root: &Path,
    manifest_sha256: &str,
    expected_model_sha256: &str,
    config_path: &Path,
    config_sha256: &str,
    config_max_bytes: u64,
    max_total_graph_bytes: u64,
    max_cache_bytes: u64,
    limit: usize,
    stop: Option<&str>,
) -> Result<()> {
    execute(
        Artifact::Directory(root),
        manifest_sha256,
        Some(expected_model_sha256),
        config_path,
        config_sha256,
        config_max_bytes,
        max_total_graph_bytes,
        max_cache_bytes,
        limit,
        stop.map(str::as_bytes),
    )
}

#[cfg(feature = "embedded-owned-cached-byte")]
pub fn generate_embedded(
    expected_manifest_sha256: &str,
    expected_model_sha256: &str,
    config_path: &Path,
    config_sha256: &str,
    config_max_bytes: u64,
    max_cache_bytes: u64,
    limit: usize,
    stop: Option<&str>,
) -> Result<()> {
    execute(
        Artifact::Embedded,
        expected_manifest_sha256,
        Some(expected_model_sha256),
        config_path,
        config_sha256,
        config_max_bytes,
        embedded::PREFILL.len() as u64 + embedded::DECODE.len() as u64,
        max_cache_bytes,
        limit,
        stop.map(str::as_bytes),
    )
}

fn execute(
    artifact: Artifact<'_>,
    manifest_sha256: &str,
    expected_model_sha256: Option<&str>,
    config_path: &Path,
    config_sha256: &str,
    config_max_bytes: u64,
    max_total_graph_bytes: u64,
    max_cache_bytes: u64,
    limit: usize,
    stop: Option<&[u8]>,
) -> Result<()> {
    if !valid_sha256(config_sha256) || !valid_sha256(manifest_sha256) {
        return Err("invalid pinned cached service identity");
    }
    match &artifact {
        Artifact::Directory(root) => {
            let metadata = std::fs::symlink_metadata(root)
                .map_err(|_| "cached artifact directory unavailable")?;
            if !metadata.file_type().is_dir() {
                return Err("cached artifact directory must be a real directory");
            }
        }
        #[cfg(feature = "embedded-owned-cached-byte")]
        Artifact::Embedded => {}
    }
    let config_raw = read_regular_bounded(config_path, config_max_bytes)?;
    if sha256(&config_raw) != config_sha256 {
        return Err("runtime configuration digest mismatch");
    }
    let runtime: RuntimeLimits =
        serde_json::from_slice(&config_raw).map_err(|_| "invalid runtime configuration")?;
    validate_runtime_limits(
        &runtime,
        limit,
        stop,
        max_total_graph_bytes,
        max_cache_bytes,
    )?;
    let manifest_raw = artifact.read("manifest.json", runtime.max_manifest_bytes)?;
    if sha256(&manifest_raw) != manifest_sha256 {
        return Err("cached manifest identity mismatch");
    }
    let manifest: Manifest =
        serde_json::from_slice(&manifest_raw).map_err(|_| "invalid cached manifest")?;
    validate_graph_contracts(
        &manifest,
        manifest_sha256,
        runtime.max_manifest_bytes,
        max_total_graph_bytes,
        max_cache_bytes,
    )?;
    if manifest.context > runtime.max_context
        || expected_model_sha256.is_some_and(|expected| expected != manifest.model_sha256)
        || manifest.cache.maximum_state_bytes_per_batch > max_cache_bytes
    {
        return Err("cached artifact exceeds configured context or cache limits");
    }
    let prefill_len = artifact.file_len("prefill.onnx", runtime.max_model_bytes)?;
    let decode_len = artifact.file_len("decode.onnx", runtime.max_model_bytes)?;
    if prefill_len
        .checked_add(decode_len)
        .ok_or("cached graph byte budget overflow")?
        > max_total_graph_bytes
    {
        return Err("cached graphs exceed total artifact byte budget");
    }
    let prefill_raw = artifact.read("prefill.onnx", runtime.max_model_bytes)?;
    let decode_raw = artifact.read("decode.onnx", runtime.max_model_bytes)?;
    let total = (prefill_raw.len() as u64)
        .checked_add(decode_raw.len() as u64)
        .ok_or("cached graph byte budget overflow")?;
    if total > max_total_graph_bytes
        || sha256(&prefill_raw) != manifest.prefill_onnx_sha256
        || sha256(&decode_raw) != manifest.decode_onnx_sha256
    {
        return Err("cached graph identity or size mismatch");
    }
    validate_graph_metadata(&prefill_raw, &decode_raw, &manifest)?;
    let prefill = configure_prefill(&prefill_raw)?;
    let decode = configure_decode(&decode_raw, &manifest.cache.states, &manifest.architecture)?;
    drop(prefill_raw);
    drop(decode_raw);
    drop(manifest_raw);

    let mut line = Vec::new();
    io::stdin()
        .lock()
        .take(runtime.max_line_bytes.saturating_add(1) as u64)
        .read_until(b'\n', &mut line)
        .map_err(|_| "cached request input read failed")?;
    if line.is_empty() || line.len() > runtime.max_line_bytes {
        return Err("cached request input is missing or oversized");
    }
    let mut trailing = [0_u8; 1];
    if io::stdin()
        .lock()
        .read(&mut trailing)
        .map_err(|_| "cached request input read failed")?
        != 0
    {
        return Err("cached worker accepts exactly one request");
    }
    let request: Request =
        serde_json::from_slice(&line).map_err(|_| "invalid cached request JSON")?;
    if request.id.trim().is_empty()
        || request.text.is_empty()
        || request.text.len() > manifest.context
        || request.text.len() > runtime.max_context
    {
        return Err("cached request input is outside the configured bounds");
    }
    let (generated, stop_reason) = generate_with_models(
        &prefill,
        &decode,
        &manifest,
        request.text.as_bytes(),
        limit,
        stop,
    )?;
    let text = std::str::from_utf8(&generated).ok();
    serde_json::to_writer(
        io::stdout().lock(),
        &Generation {
            schema_version: "lfg.owned-byte-generation.v1",
            id: &request.id,
            input_bytes: request.text.len(),
            generated_bytes: &generated,
            text,
            stop_reason,
        },
    )
    .map_err(|_| "cached generation response serialization failed")?;
    writeln!(io::stdout().lock()).map_err(|_| "cached generation response write failed")?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn small_architecture(kernel: usize, attention_every: usize) -> Architecture {
        Architecture {
            width: 8,
            layers: 2,
            heads: 2,
            conv_kernel: kernel,
            context: 4,
            ff_multiplier: 2,
            attention_every,
        }
    }

    fn private_runtime_bounds() -> RuntimeLimits {
        RuntimeLimits {
            schema_version: "lfg.owned-byte-runtime.v1".to_owned(),
            max_manifest_bytes: 1_048_576,
            max_model_bytes: 104_857_600,
            max_context: 4_352,
            max_line_bytes: 65_536,
            max_generation_bytes: Some(512),
            max_examples: Some(1_000),
        }
    }

    #[test]
    fn runtime_limits_accept_configured_boundary_and_reject_excess() {
        let runtime = private_runtime_bounds();
        assert!(validate_runtime_limits(&runtime, 512, None, 171_594_288, 71_335_936).is_ok());
        assert_eq!(
            validate_runtime_limits(&runtime, 513, None, 171_594_288, 71_335_936),
            Err("cached generation limit exceeds runtime maximum")
        );
        assert_eq!(
            validate_runtime_limits(&runtime, 512, Some(&[0; 513]), 171_594_288, 71_335_936),
            Err("cached stop sequence exceeds generation limit")
        );
        assert_eq!(
            validate_runtime_limits(&runtime, 512, None, 0, 71_335_936),
            Err("cached graph or cache-state limit is zero")
        );
    }

    #[test]
    fn manifest_layer_bounds_reject_huge_empty_state_architecture_before_iteration() {
        let huge = Architecture {
            width: 8,
            layers: usize::MAX,
            heads: 2,
            conv_kernel: 1,
            context: 4,
            ff_multiplier: 2,
            attention_every: usize::MAX,
        };
        assert_eq!(
            validate_architecture_resource_bounds(&huge, 1_048_576, u64::MAX),
            Err("cached model layers exceed configured structural bounds")
        );
        let normal = small_architecture(3, 2);
        assert_eq!(
            validate_architecture_resource_bounds(&normal, 1_048_576, 383),
            Err("cached state exceeds configured cache-state bound")
        );
    }

    #[test]
    fn cache_layout_and_resource_bytes_are_checked_and_support_kernel_one() {
        let with_attention = small_architecture(3, 2);
        let states = expected_states(&with_attention).unwrap();
        assert_eq!(
            states
                .iter()
                .map(|state| state.name.as_str())
                .collect::<Vec<_>>(),
            ["conv_0", "conv_1", "key_1", "value_1"]
        );
        assert_eq!(expected_state_bytes(&with_attention, &states).unwrap(), 384);
        let no_conv_state = small_architecture(1, 2);
        assert_eq!(expected_states(&no_conv_state).unwrap().len(), 2);
        let no_attention = small_architecture(3, 4);
        let no_attention_states = expected_states(&no_attention).unwrap();
        assert_eq!(no_attention_states.len(), 2);
        assert!(
            no_attention_states
                .iter()
                .all(|state| state.kind == "depthwise-convolution-history")
        );
    }

    #[test]
    fn context_generation_can_predict_once_at_full_context_but_never_evicts() {
        assert_eq!(next_decode_position(4, 1, 4), None);
        assert_eq!(next_decode_position(3, 1, 4), Some(3));
        assert_eq!(next_decode_position(3, 2, 4), None);
        assert_eq!(next_decode_position(1, 0, 4), None);
    }
}
